from google.cloud import logging_v2

def query_error_logs(project_id: str, severity: str = 'ERROR', start_time: str = None, end_time: str = None) -> list:
    client = logging_v2.LoggingServiceV2Client()
    project_path = f'projects/{project_id}'

    filter_expr = f'severity={severity}'
    if start_time:
        filter_expr += f' AND timestamp>={start_time}'
    if end_time:
        filter_expr += f' AND timestamp<={end_time}'

    entries = []
    for entry in client._list_log_entries(project_path, filter_expr=filter_expr):
        entries.append({
            'timestamp': entry.timestamp.isoformat(),
            'payload': entry.json_payload if entry.json_payload else entry.text_payload,
            'resource': str(entry.resource),
        })

    return entries
